var n=`0990-lu-rou-fan`;var a=`world-0990`;var o=`TW`;var r=`east-asia`;var s=4;var t=115;var l={en:`Lu Rou Fan`,ua:`Лу жоу фань`};var d={en:`Lu Rou Fan is a Taiwan dish made with calrose rice, ground pork, red onion, garlic. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Лу жоу фань, страва кухні країни Тайвань. Основні складники: рис калроуз, свинячий фарш, червона цибуля, часник. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var u=[{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 23 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 23 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:23,i:[[`calrose-rice`,440,`g`],[`water`,790,`ml`]]},{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 13 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 13 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:13,i:[[`ground-pork`,600,`g`],[`canola-oil`,38,`ml`],[`red-onion`,180,`g`],[`garlic`,5,`clove`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 65 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 65 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:65,i:[[`light-soy-sauce`,80,`ml`],[`dark-soy-sauce`,40,`ml`],[`shaoxing-wine`,65,`ml`],[`star-anise`,2,`pcs`],[`white-granulated-sugar`,35,`g`],[`water`,420,`ml`]]},{en:`Boil the eggs for about 9 minutes, cool promptly in cold water, peel and prepare as required.`,ua:`Варіть яйця приблизно 9 хвилин, швидко охолодіть у холодній воді, очистьте та підготуйте за потреби.`,t:[`hard-boiling-eggs`],m:9,i:[[`chicken-egg`,4,`pcs`]]},{en:`Arrange the prepared cooked components and listed toppings in a serving dish, keeping hot foods hot and chilled components cold until serving.`,ua:`Складіть готові приготовлені компоненти й зазначені додатки в посуді для подавання, підтримуючи гаряче гарячим, а холодне охолодженим.`,t:[`layered-assembly`,`garnishing`],m:5,i:[[`pickled-cucumber`,160,`g`]]}];var g={slug:n,id:a,country:`TW`,region:r,servings:4,minutes:115,title:l,text:d,steps:u};export{o as country,g as default,a as id,t as minutes,r as region,s as servings,n as slug,u as steps,d as text,l as title};